/* Hollowroot prototype: state, turn rules, AI, rendering, and UI. */
(() => {
  'use strict';
  const canvas = document.querySelector('#game-canvas'), ctx = canvas.getContext('2d');
  ctx.imageSmoothingEnabled = false;
  const W=20,H=14,T=32,$=s=>document.querySelector(s), dirs=[[1,0],[-1,0],[0,1],[0,-1]];
  const species={
    wayfarer:{name:'Wayfarer',role:'Lantern keeper',icon:'⌂',color:'#d8b67a',maxHp:9,damage:2,range:1,blurb:'A steady hand and a stubborn lantern.'},
    bramblet:{name:'Bramblet',role:'Briarback · bulwark',icon:'♣',color:'#95bd70',maxHp:10,damage:3,range:1,blurb:'Round and sturdy. Its thorny tackle hits hard.'},
    cindercub:{name:'Cindercub',role:'Cinderkin · striker',icon:'✦',color:'#ed9564',maxHp:7,damage:3,range:1,blurb:'Quick-footed and fierce. A clean pounce deals 3.'},
    morrowisp:{name:'Morrowisp',role:'Gloamling · farseer',icon:'◉',color:'#8ebfc0',maxHp:6,damage:2,range:3,blurb:'A drifting lantern spirit. Its glow reaches three tiles.'}
  };
  const S={screen:'hub',party:[],wilds:[],enemies:[],loot:[],walls:new Set(),selected:0,round:1,embers:0,supplies:0,run:1,upgrade:4,notes:[],sound:false,audio:null,startAt:0,won:false};
  const dist=(a,b)=>Math.abs(a.x-b.x)+Math.abs(a.y-b.y), unit=(kind,x,y,id)=>({id,kind,x,y,hp:species[kind].maxHp,maxHp:species[kind].maxHp,damage:species[kind].damage,range:species[kind].range,acted:false,alive:true});
  const me=()=>S.party[S.selected], key=(x,y)=>`${x},${y}`, inside=(x,y)=>x>=0&&y>=0&&x<W&&y<H;
  function log(text){S.notes.unshift(text);S.notes=S.notes.slice(0,4);renderLog()}
  function say(text){const e=$('#toast');e.textContent=text;e.classList.remove('hidden');e.style.animation='none';void e.offsetWidth;e.style.animation='';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>e.classList.add('hidden'),2300)}
  function beep(freq=360,duration=.06){if(!S.sound)return;try{const a=S.audio||(S.audio=new(window.AudioContext||window.webkitAudioContext)()),o=a.createOscillator(),g=a.createGain();o.type='square';o.frequency.value=freq;g.gain.value=.025;o.connect(g);g.connect(a.destination);o.start();g.gain.exponentialRampToValueAtTime(.001,a.currentTime+duration);o.stop(a.currentTime+duration)}catch{}}
  function initCamp(){S.party=[unit('wayfarer',1,1,'lead'),unit('bramblet',2,1,'bramblet')];S.wilds=[];S.enemies=[];S.loot=[];S.notes=[];S.round=1;S.selected=0;S.supplies=0;S.party.forEach(p=>{p.hp=p.maxHp;p.acted=false;p.alive=true})}
  function renderRoster(){const root=$('#hub-roster');root.innerHTML='';S.party.forEach(p=>{const s=species[p.kind],row=document.createElement('div');row.className='crew-row';row.innerHTML=`<div class="creature-icon" style="color:${s.color}">${s.icon}</div><div class="creature-info"><strong>${s.name}</strong><small>${s.role}</small></div><span class="roster-state">READY</span>`;root.appendChild(row)});$('#crew-count').textContent=`${S.party.length} / 4`;$('#hub-embers').textContent=S.embers;$('#upgrade-cost').textContent=S.upgrade;renderUpgrades()}
  function renderUpgrades(){const root=$('#upgrade-options');root.innerHTML='';S.party.forEach(p=>{const b=document.createElement('button');b.className='upgrade-option';b.innerHTML=`${species[p.kind].name}<small>+2 max hearts</small>`;b.disabled=S.embers<S.upgrade||p.maxHp>=16;b.onclick=()=>{S.embers-=S.upgrade;p.maxHp+=2;p.hp+=2;S.upgrade+=2;renderRoster();say(`${species[p.kind].name} feels a little sturdier.`);beep(540,.12)};root.appendChild(b)})}
  function setupDungeon(){S.screen='dungeon';S.round=1;S.selected=0;S.supplies=0;S.startAt=Date.now();S.notes=[];S.won=false;
    // Hand-shaped rooms are stitched with procedural rubble, leaving clear lanes through the grotto.
    const rows=['####################','#..................#','#..##.......#......#','#..#........#..#...#','#..#..###......#...#','#.....#............#','#.....#..####......#','#..................#','#....##............#','#..........###.....#','#..........#.......#','#..........#.......#','#..................#','####################'];
    S.walls=new Set();for(let y=0;y<H;y++)for(let x=0;x<W;x++)if(rows[y][x]==='#')S.walls.add(key(x,y));
    // Tiny seeded decorative blockers add a distinct shape to each descent without ever sealing a room.
    for(let i=0;i<5;i++){const x=5+Math.floor(Math.random()*9),y=2+Math.floor(Math.random()*9);if(!S.walls.has(key(x,y))&&!(x===8&&y===6))S.walls.add(key(x,y))}
    S.party.forEach((p,i)=>{p.x=1+i;p.y=1;p.hp=p.maxHp;p.acted=false;p.alive=true});S.wilds=[unit('cindercub',4,7,'wild-cinder'),unit('morrowisp',2,10,'wild-wisp')];
    S.enemies=[{...unit('mossmote',9,3,'mossmote-a'),kind:'mossmote',name:'Mossmote',damage:2,range:1},{...unit('mossmote',15,7,'mossmote-b'),kind:'mossmote',name:'Mossmote',damage:2,range:1},{...unit('mossmote',16,10,'mossmote-c'),kind:'mossmote',name:'Mossmote',damage:2,range:1},{...unit('rootmaw',17,2,'rootmaw'),kind:'rootmaw',name:'Rootmaw',damage:3,range:1,hp:12,maxHp:12}];
    S.loot=[{x:5,y:3,type:'cache',opened:false},{x:12,y:8,type:'cache',opened:false},{x:18,y:12,type:'exit',opened:false}];
    $('#hub-screen').classList.add('hidden');$('#dungeon-screen').classList.remove('hidden');$('#page-title').textContent='Every step is a small promise.';$('#page-copy').textContent='Move your crew, watch their footing, and make the shadows answer.';$('#eyebrow').textContent='A TURN-BASED DESCENT';$('#run-number').textContent=String(S.run).padStart(2,'0');$('#event-log').innerHTML='';log('Your lantern finds the Mosslight Grotto.');log('Recruit a wildshape with E when you stand beside it.');render();say('Find the two wild companions, then clear the grotto.');
  }
  function occupied(x,y,ignore){return S.walls.has(key(x,y))||S.party.some(p=>p.alive&&p.id!==ignore&&p.x===x&&p.y===y)||S.wilds.some(p=>p.alive&&p.x===x&&p.y===y)||S.enemies.some(e=>e.alive&&e.x===x&&e.y===y)}
  function canAct(p=me()){return S.screen==='dungeon'&&p&&p.alive&&!p.acted}
  function onAlly(x,y){return S.party.find(p=>p.alive&&p.x===x&&p.y===y)}
  function onEnemy(x,y){return S.enemies.find(e=>e.alive&&e.x===x&&e.y===y)}
  function onWild(x,y){return S.wilds.find(e=>e.alive&&e.x===x&&e.y===y)}
  function allActed(){return S.party.filter(p=>p.alive).every(p=>p.acted)}
  function finishAction(p,msg){p.acted=true;if(msg)log(msg);beep();render();if(allActed())setTimeout(enemyPhase,220)}
  function move(dx,dy){const p=me();if(!canAct(p))return;const x=p.x+dx,y=p.y+dy;if(!inside(x,y)||occupied(x,y,p.id)){say('That tile is blocked.');return}p.x=x;p.y=y;finishAction(p,`${species[p.kind].name} steps into the gloom.`);checkExit()}
  function attack(target){const p=me();if(!canAct(p)||!target)return;const d=dist(p,target);if(d>p.range){say(`Too far. ${species[p.kind].name} reaches ${p.range} tile${p.range>1?'s':''}.`);return}target.hp-=p.damage;log(`${species[p.kind].name} hits ${target.name||species[target.kind].name} for ${p.damage}.`);beep(180,.1);if(target.hp<=0){target.alive=false;log(`${target.name||species[target.kind].name} crumples into spores.`);S.embers+=target.kind==='rootmaw'?5:1;renderRoster()}finishAction(p);if(!S.enemies.some(e=>e.alive)){say('The grotto is quiet. The exit is open.');log('The root gate has woken. Find the green-lit arch.')}}
  function tryAttack(){const p=me();if(!canAct(p))return;const targets=S.enemies.filter(e=>e.alive&&dist(p,e)<=p.range).sort((a,b)=>dist(p,a)-dist(p,b));if(!targets.length){say('No wildshape in reach.');return}attack(targets[0])}
  function recruit(){const p=me();if(!canAct(p))return;const w=S.wilds.find(e=>e.alive&&dist(p,e)<=1);if(!w){const chest=S.loot.find(l=>l.type==='cache'&&!l.opened&&dist(p,l)<=1);if(chest){chest.opened=true;S.supplies+=2;S.embers+=2;log('You found 2 gloam embers and a warm nutcake.');finishAction(p,'A little cache, tucked under a root.');renderRoster();return}const exit=S.loot.find(l=>l.type==='exit'&&dist(p,l)<=1);if(exit){if(S.enemies.some(e=>e.alive)){say('The root gate is sealed. Clear every wildshape first.');return}completeRun(true);return}say('Nothing close enough to interact with.');return}
    if(S.party.length>=4){say('Your crew is full.');return}w.alive=false;w.acted=false;w.x=p.x;w.y=p.y;S.party.push(w);S.selected=S.party.length-1;log(`${species[w.kind].name} joins your crew!`);beep(620,.14);render();if(allActed())setTimeout(enemyPhase,220)}
  function enemyPhase(){if(S.screen!=='dungeon'||S.won)return;$('#turn-status').textContent='WILDSHAPES ACT';S.party.forEach(p=>p.acted=false);const foes=S.enemies.filter(e=>e.alive);for(const e of foes){if(!e.alive)continue;const targets=S.party.filter(p=>p.alive);if(!targets.length)break;targets.sort((a,b)=>dist(e,a)-dist(e,b));const target=targets[0],d=dist(e,target);if(d<=e.range){target.hp-=e.damage;log(`${e.name} lashes ${species[target.kind].name} for ${e.damage}.`);beep(100,.08);if(target.hp<=0){target.alive=false;log(`${species[target.kind].name} is knocked out!`);if(target.kind==='wayfarer'){render();setTimeout(()=>completeRun(false),500)}}}else{const options=dirs.map(([dx,dy])=>({x:e.x+dx,y:e.y+dy})).filter(q=>inside(q.x,q.y)&&!occupied(q.x,q.y,e.id)).sort((a,b)=>dist(a,target)-dist(b,target));if(options.length){e.x=options[0].x;e.y=options[0].y}}}
    S.party=S.party.filter((p,i)=>p.kind==='wayfarer'||p.alive);if(!S.party.some(p=>p.kind==='wayfarer'))return;S.selected=Math.min(S.selected,S.party.length-1);S.round++;$('#turn-status').textContent='YOUR TURN';log('Your crew catches its breath.');render();}
  function endTurn(){if(S.screen!=='dungeon')return;S.party.filter(p=>p.alive).forEach(p=>p.acted=true);enemyPhase()}
  function checkExit(){const exit=S.loot.find(l=>l.type==='exit');const p=me();if(exit&&p.x===exit.x&&p.y===exit.y){if(S.enemies.some(e=>e.alive)){say('The root gate is sealed. Clear every wildshape first.');return}completeRun(true)}}
  function completeRun(won){if(S.won)return;S.won=true;S.screen='result';const duration=Math.floor((Date.now()-S.startAt)/60000),hauls=won?Math.max(3,3+S.supplies):Math.max(1,Math.floor(S.supplies/2));S.embers+=hauls;$('#result-eyebrow').textContent=won?'BACK AT THIMBLEWICK':'A QUIET RETURN TO CAMP';$('#result-title').textContent=won?'A good little haul.':'The grotto keeps its secrets.';$('#result-copy').textContent=won?'The root gate lets you back into the lanternlight. Your new friends come with you.':`You made it back with ${Math.max(1,S.party.length)} friend${S.party.length===1?'':'s'}. The crew will be ready for another try.`;$('#result-rewards').innerHTML=`<div class="reward"><strong>✦ ${hauls}</strong><small>GLOAM EMBERS</small></div><div class="reward"><strong>${S.party.filter(p=>p.kind!=='wayfarer').length}</strong><small>COMPANIONS</small></div><div class="reward"><strong>${duration}m</strong><small>IN THE GROTTO</small></div>`;$('#result-modal').classList.remove('hidden');renderRoster()}
  function backToCamp(){S.run++;initCamp();$('#result-modal').classList.add('hidden');$('#dungeon-screen').classList.add('hidden');$('#hub-screen').classList.remove('hidden');$('#page-title').textContent='The roots run deeper.';$('#page-copy').textContent='Gather your odd little crew. Make every step count. Find the way back before the dark finds you.';$('#eyebrow').textContent='A SMALL-SCALE CREATURE ROGUELITE';$('#run-number').textContent=String(S.run).padStart(2,'0');renderRoster()}

