function renderLog(){const root=$('#event-log');root.innerHTML='';S.notes.slice(0,4).forEach(n=>{const li=document.createElement('li');li.textContent=n;root.appendChild(li)})}
function renderParty(){const root=$('#party-list');root.innerHTML='';S.party.forEach((p,i)=>{const s=species[p.kind],b=document.createElement('button');b.className=`party-chip${i===S.selected?' active':''}${p.acted?' spent':''}`;b.innerHTML=`<div class="chip-head"><span class="chip-emoji" style="color:${s.color}">${s.icon}</span><span class="chip-key">${i===0?'LEAD':i}</span></div><strong>${s.name}</strong><div class="hp-track"><div class="hp-fill ${p.hp<=p.maxHp*.35?'low':''}" style="width:${Math.max(0,p.hp/p.maxHp*100)}%"></div></div>`;b.onclick=()=>{S.selected=i;render()};root.appendChild(b)});const p=me();if(p){const s=species[p.kind];$('#selected-card').innerHTML=`<div class="selected-title"><strong style="color:${s.color}">${s.name}</strong><span>${p.hp}/${p.maxHp} ♥ · ${p.damage} ATK</span></div><p>${s.blurb} ${p.range>1?`Reach: ${p.range} tiles.`:'Reach: adjacent.'}</p>`}$('#turn-number').textContent=String(S.round).padStart(2,'0');$('#end-turn').disabled=!S.party.some(p=>!p.acted&&p.alive)}
function render(){if(S.screen!=='dungeon')return;renderParty();draw()}
function draw(){ctx.clearRect(0,0,canvas.width,canvas.height);for(let y=0;y<H;y++)for(let x=0;x<W;x++)drawTile(x,y);S.loot.forEach(drawLoot);S.wilds.filter(u=>u.alive).forEach((u,i)=>drawCreature(u,true,i));S.enemies.filter(e=>e.alive).forEach(drawCreature);S.party.filter(p=>p.alive).forEach((p,i)=>drawCreature(p,false,i));const p=me();if(p){ctx.strokeStyle='#e2edaf';ctx.lineWidth=2;ctx.strokeRect(p.x*T+2,p.y*T+2,T-4,T-4);if(!p.acted){for(const [dx,dy] of dirs){const x=p.x+dx,y=p.y+dy;if(inside(x,y)&&!occupied(x,y,p.id)){ctx.fillStyle='#c2df7d20';ctx.fillRect(x*T+1,y*T+1,T-2,T-2)}}}}}
function drawTile(x,y){const X=x*T,Y=y*T,wall=S.walls.has(key(x,y)),n=(x*31+y*73)%5;if(wall){ctx.fillStyle=['#202a27','#26312c','#28332d','#212d29','#303831'][n];ctx.fillRect(X,Y,T,T);ctx.fillStyle='#3b4438';ctx.fillRect(X,Y,T,3);ctx.fillStyle='#141e1b';ctx.fillRect(X,Y+T-4,T,4);ctx.fillStyle='#354036';ctx.fillRect(X+5+(n%3)*7,Y+9,3,2);if(n===1){ctx.fillStyle='#4a4b38';ctx.fillRect(X+20,Y+17,5,4)}}else{ctx.fillStyle=['#39443a','#3b463b','#364239','#3d483d','#39453b'][n];ctx.fillRect(X,Y,T,T);ctx.fillStyle='#414b3d';ctx.fillRect(X+2,Y+2,T-4,T-4);ctx.fillStyle='#48503c';ctx.fillRect(X+4+(n%3)*7,Y+6,3,2);ctx.fillStyle='#313d35';ctx.fillRect(X+6,Y+23,4,2);if((x*13+y*7)%11===0){ctx.fillStyle='#83945a';ctx.fillRect(X+23,Y+20,2,4);ctx.fillRect(X+21,Y+19,2,2)}}ctx.strokeStyle='#202b26';ctx.lineWidth=1;ctx.strokeRect(X+.5,Y+.5,T,T)}
function drawLoot(l){const x=l.x*T,y=l.y*T;if(l.type==='exit'){ctx.fillStyle=S.enemies.some(e=>e.alive)?'#77564b':'#9aaa69';ctx.fillRect(x+5,y+5,22,25);ctx.fillStyle='#27332e';ctx.fillRect(x+9,y+8,14,22);ctx.fillStyle=S.enemies.some(e=>e.alive)?'#c77750':'#d8dc9c';ctx.fillRect(x+13,y+12,6,3);ctx.fillRect(x+7,y+3,18,3);ctx.fillStyle='#a5b976';ctx.fillRect(x+7,y+8,3,19);ctx.fillRect(x+22,y+8,3,19)}else if(!l.opened){ctx.fillStyle='#79563a';ctx.fillRect(x+7,y+14,18,13);ctx.fillStyle='#b88a50';ctx.fillRect(x+6,y+11,20,6);ctx.fillStyle='#d2af6c';ctx.fillRect(x+14,y+16,4,5);ctx.fillStyle='#91653f';ctx.fillRect(x+9,y+23,14,3)}else{ctx.fillStyle='#9c8350';ctx.fillRect(x+13,y+22,7,3)}}
