  function selectNext(){if(!S.party.length)return;for(let i=1;i<=S.party.length;i++){const n=(S.selected+i)%S.party.length;if(S.party[n].alive&&!S.party[n].acted){S.selected=n;render();return}}const n=S.party.findIndex(p=>p.alive);if(n>=0){S.selected=n;render()}}
  function clickBoard(ev){if(S.screen!=='dungeon')return;const r=canvas.getBoundingClientRect(),x=Math.floor((ev.clientX-r.left)*W/r.width),y=Math.floor((ev.clientY-r.top)*H/r.height);if(!inside(x,y))return;const friend=onAlly(x,y);if(friend){S.selected=S.party.indexOf(friend);render();return}const foe=onEnemy(x,y);if(foe){attack(foe);return}const wild=onWild(x,y);if(wild){if(me()&&dist(me(),wild)<=1)recruit();else say('Stand beside a wildshape to invite it.');return}const p=me();if(!p)return;if(S.loot.some(l=>l.x===x&&l.y===y&&l.type==='exit')){if(dist(p,{x,y})<=1)recruit();else say('Move beside the root gate to leave.');return}if(S.loot.some(l=>l.x===x&&l.y===y&&l.type==='cache'&&!l.opened)){if(dist(p,{x,y})<=1)recruit();else say('Move beside the cache to open it.');return}const dx=x-p.x,dy=y-p.y;if(Math.abs(dx)+Math.abs(dy)===1)move(dx,dy);else say('Choose an adjacent tile to move.')}
  window.addEventListener('keydown',e=>{if(S.screen!=='dungeon'||!$('#result-modal').classList.contains('hidden'))return;const k=e.key.toLowerCase();if(['arrowup','arrowdown','arrowleft','arrowright',' '].includes(k))e.preventDefault();if(k==='arrowup'||k==='w')move(0,-1);else if(k==='arrowdown'||k==='s')move(0,1);else if(k==='arrowleft'||k==='a')move(-1,0);else if(k==='arrowright'||k==='d')move(1,0);else if(k===' ')tryAttack();else if(k==='e')recruit();else if(k==='tab'){e.preventDefault();selectNext()}else if(k==='enter')endTurn();else if(/^[1-4]$/.test(k)){const i=Number(k)-1;if(S.party[i]){S.selected=i;render()}}});
