const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright-core');
(async () => {
  const browser = await chromium.launch({ executablePath: '/usr/bin/chromium', headless: true, args: ['--no-sandbox'] });
  const page = await browser.newPage({ viewport: { width: 1440, height: 1000 } });
  const errors = [];
  page.on('pageerror', error => errors.push(error.message));
  await page.route('**/game.js', async route => {
    const response = await route.fetch();
    const source = (await response.text()).replace('initCamp();renderRoster();', 'window.__test={S,setupDungeon,recruit};initCamp();renderRoster();');
    await route.fulfill({ response, body: source });
  });
  await page.goto('http://localhost:3002');
  await page.locator('#start-run').click();
  const initial = await page.evaluate(() => ({ phase: window.__test.S.phase, party: window.__test.S.party.length, foes: window.__test.S.enemies.length }));
  await page.evaluate(() => {
    const {S}=window.__test;
    S.party[0].x=3; S.party[0].y=7;
    S.party[1].x=2; S.party[1].y=1;
    S.selected=0;
  });
  await page.keyboard.press('e');
  await page.waitForTimeout(20);
  const recruited = await page.evaluate(() => {
    const {S}=window.__test;
    return { count:S.party.length, kind:S.party[2].kind, companion:[S.party[2].x,S.party[2].y], leader:[S.party[0].x,S.party[0].y], log:[...document.querySelectorAll('#event-log li')].map(e=>e.textContent) };
  });
  const layout = await page.evaluate(() => ({ viewport:innerWidth, document:document.documentElement.scrollWidth, visibleCanvas:document.querySelector('#game-canvas').getBoundingClientRect().width }));
  await page.setViewportSize({ width: 390, height: 844 });
  const mobile = await page.evaluate(() => ({ viewport:innerWidth, document:document.documentElement.scrollWidth, canvas:document.querySelector('#game-canvas').getBoundingClientRect().width }));
  await page.screenshot({ path: '/tmp/opencode/hollowroot-mobile.png', fullPage: true });
  console.log(JSON.stringify({ initial, recruited, layout, mobile, errors }, null, 2));
  if(initial.phase!=='player'||initial.party!==2||initial.foes!==4) throw new Error('Unexpected expedition setup');
  if(recruited.count!==3||recruited.kind!=='cindercub'||recruited.companion.join(',')==='3,7') throw new Error('Recruitment placement failed');
  if(errors.length) throw new Error(errors.join('; '));
  if(mobile.document>mobile.viewport+1) throw new Error('Mobile layout overflows horizontally');
  await browser.close();
})().catch(error => { console.error(error); process.exit(1); });
